using System.Diagnostics;
using System.Security.Cryptography;
using System.Text.Json;
using ChappyStorageCompressor.Core;

// R2.17 bulk priority matrix (generated bytes only, never personal media).
internal static class R217PriorityBulkScannerTests
{
    private const int UniqueCount = 1024;
    private const int SameSizeCount = 48;
    private const int RepeatedBytes = 65536;
    private sealed record Sample(string Dataset, string Pass, int FileCount,
        int DeepInspectedFiles, int HashAttemptedFiles, int VerifiedGroups,
        double ElapsedMs, long CallingThreadManagedBytes, long WorkingSetAfterBytes);

    private static string Hash(string path)
    {
        using var stream = File.OpenRead(path);
        return Convert.ToHexString(SHA256.HashData(stream));
    }

    private static Sample Measure(string path, string dataset, string pass,
        int count, int deep, int hash, int groups)
    {
        long startBytes = GC.GetAllocatedBytesForCurrentThread();
        var watch = Stopwatch.StartNew();
        var result = Scanner.Run(path, true, null, CancellationToken.None);
        watch.Stop();
        using var process = Process.GetCurrentProcess();
        process.Refresh();
        if (result.FileCount != count || result.DeepInspectedFiles != deep ||
            result.HashAttemptedFiles != hash || result.Groups.Count != groups ||
            result.Errors != 0)
            throw new InvalidDataException($"Unexpected scanner counts in {dataset}/{pass}");
        return new Sample(dataset, pass, result.FileCount,
            result.DeepInspectedFiles, result.HashAttemptedFiles,
            result.Groups.Count, watch.Elapsed.TotalMilliseconds,
            GC.GetAllocatedBytesForCurrentThread() - startBytes,
            process.WorkingSet64);
    }

    public static void Run(string parent, Action<bool, string> check)
    {
        string root = Path.Combine(parent, "r217-priority-bulk-scanner-only");
        string unique = Path.Combine(root, "unique");
        string collisions = Path.Combine(root, "collision");
        Directory.CreateDirectory(unique);
        Directory.CreateDirectory(collisions);
        try
        {
            // Sizes are unique even across nested directories; fast shallow
            // inventory must NOT cause any SHA reads or NTFS deep inspection.
            var uniqueFiles = new List<string>(UniqueCount);
            for (int i = 0; i < UniqueCount; i++)
            {
                string sub = Path.Combine(unique, $"folder-{i / 256}");
                Directory.CreateDirectory(sub);
                string ext = (i % 3) switch { 0 => ".jpg", 1 => ".png", _ => ".mp4" };
                string path = Path.Combine(sub, $"synthetic-{i:D4}{ext}");
                byte[] data = new byte[512 + i * 7];
                new Random(217400 + i).NextBytes(data);
                File.WriteAllBytes(path, data);
                uniqueFiles.Add(path);
            }
            // 48 deliberate same-size collisions; exactly four independent
            // exact duplicate pairs, the other 40 are independent random bytes.
            var collisionFiles = new List<string>(SameSizeCount);
            for (int i = 0; i < SameSizeCount; i++)
            {
                int pairSeed = i < 8 ? i / 2 : i;
                string ext = ((i / 2) % 3) switch { 0 => ".jpg", 1 => ".png", _ => ".mp4" };
                string path = Path.Combine(collisions, $"collision-{i:D2}{ext}");
                byte[] bytes = new byte[RepeatedBytes];
                new Random(218000 + pairSeed).NextBytes(bytes);
                File.WriteAllBytes(path, bytes);
                if (i < 8 && i % 2 == 1)
                {
                    string prev = collisionFiles[i - 1];
                    File.SetCreationTimeUtc(path, File.GetCreationTimeUtc(prev));
                    File.SetLastWriteTimeUtc(path, File.GetLastWriteTimeUtc(prev));
                }
                collisionFiles.Add(path);
            }
            long sourceBytes = uniqueFiles.Concat(collisionFiles)
                .Sum(p => new FileInfo(p).Length);
            var sampledHashes = collisionFiles.ToDictionary(p => p, Hash);
            var sampledTicks = collisionFiles.ToDictionary(p => p,
                p => File.GetLastWriteTimeUtc(p).Ticks);
            check(uniqueFiles.Count == UniqueCount &&
                  collisionFiles.Count == SameSizeCount &&
                  uniqueFiles.Distinct(StringComparer.OrdinalIgnoreCase).Count() == UniqueCount,
                "R2.17 bulk: 1,024 independent nested unique-size files and 48 same-size collisions generated");
            var samples = new List<Sample>();
            for (int pass = 0; pass < 2; pass++)
            {
                string run = pass == 0 ? "first-cache-uncontrolled" : "repeat-cache-uncontrolled";
                var u = Measure(unique, "unique-sizes", run, UniqueCount, 0, 0, 0);
                var c = Measure(collisions, "same-size", run,
                    SameSizeCount, SameSizeCount, SameSizeCount, 4);
                samples.Add(u);
                samples.Add(c);
                check(u.DeepInspectedFiles == 0 && u.HashAttemptedFiles == 0 &&
                      c.DeepInspectedFiles == 48 && c.HashAttemptedFiles == 48,
                    "R2.17 bulk: shallow inventory avoids all needless SHA/NTFS work; collisions stay strict");
                check(u.ElapsedMs > 0 && c.ElapsedMs > 0 &&
                      u.CallingThreadManagedBytes >= 0 &&
                      c.CallingThreadManagedBytes >= 0,
                    "R2.17 bulk: separate first and repeated wall/managed allocation metrics captured");
            }
            // Reference ground truth from framework SHA-256, completely
            // independent of the application's two-stage scanner.
            var groundTruth = collisionFiles.GroupBy(Hash)
                .Where(g => g.Count() > 1)
                .Select(g => string.Join("|", g.Select(Path.GetFileName)
                    .OrderBy(x => x, StringComparer.Ordinal)))
                .OrderBy(x => x, StringComparer.Ordinal).ToArray();
            var expected = Enumerable.Range(0, 4)
                .Select(pair => string.Join("|",
                    new[] { Path.GetFileName(collisionFiles[2 * pair]),
                            Path.GetFileName(collisionFiles[2 * pair + 1]) }
                    .OrderBy(x => x, StringComparer.Ordinal)))
                .OrderBy(x => x, StringComparer.Ordinal).ToArray();
            check(groundTruth.SequenceEqual(expected) &&
                  expected.All(pair =>
                  {
                      string[] names = pair.Split('|');
                      return File.ReadAllBytes(Path.Combine(collisions, names[0]))
                          .AsSpan().SequenceEqual(File.ReadAllBytes(Path.Combine(collisions, names[1])));
                  }),
                "R2.17 bulk: four exact duplicate pairs independently SHA and byte authenticated");
            var actual = Scanner.Run(collisions, true, null, CancellationToken.None)
                .Groups.Select(g => string.Join("|", g.Files.Select(f => Path.GetFileName(f.Path))
                    .OrderBy(x => x, StringComparer.Ordinal)))
                .OrderBy(x => x, StringComparer.Ordinal).ToArray();
            check(actual.SequenceEqual(expected),
                "R2.17 bulk: actual 48-file scanner groups equal independent duplicate oracle");
            check(sampledHashes.All(x => Hash(x.Key) == x.Value &&
                      File.GetLastWriteTimeUtc(x.Key).Ticks == sampledTicks[x.Key]),
                "R2.17 bulk: all same-size sources SHA-256 and timestamps preserved");

            using var canceled = new CancellationTokenSource();
            canceled.Cancel();
            bool cancelConfirmed = false;
            try { Scanner.Run(collisions, true, null, canceled.Token); }
            catch (OperationCanceledException) { cancelConfirmed = true; }
            check(cancelConfirmed && samples.Count == 4,
                "R2.17 bulk: explicit canceled duplicate scan never yields partial groups");

            // G1-04: reuse all 1,072 generated files to prove that a
            // brand-new scan after cancellation produces the exact same
            // independent oracle, without making a new benchmark project.
            var restarted = Scanner.Run(root, true, null, CancellationToken.None);
            string[] restartedGroups = restarted.Groups
                .Select(g => string.Join("|", g.Files.Select(f =>
                    Path.GetFileName(f.Path)).OrderBy(x => x, StringComparer.Ordinal)))
                .OrderBy(x => x, StringComparer.Ordinal).ToArray();
            check(restarted.FileCount == UniqueCount + SameSizeCount &&
                  restarted.DeepInspectedFiles == SameSizeCount &&
                  restarted.HashAttemptedFiles == SameSizeCount &&
                  restarted.Groups.Count == 4 &&
                  restartedGroups.SequenceEqual(expected) &&
                  restarted.SkipReasons.Values.Sum() == restarted.Skipped &&
                  restarted.ErrorReasons.Values.Sum() == restarted.Errors,
                "G1-04: after cancellation a full 1,072-file rescan matches all independent SHA/byte groups and exact exclusion counts");

            Directory.CreateDirectory("diagnostics");
            File.WriteAllText("diagnostics/r217-priority-bulk-scan.json",
                JsonSerializer.Serialize(new
                {
                    schema = "chappy-r217-priority-matrix-scan-v1",
                    uniqueSourceCount = UniqueCount,
                    collisionSourceCount = SameSizeCount,
                    totalSyntheticFiles = UniqueCount + SameSizeCount,
                    generatedSourceBytes = sourceBytes,
                    independentReferenceDuplicatePairs = 4,
                    exactDuplicatePairsAllMatch = true,
                    allOriginalHashesAndTimestampsPreserved = true,
                    cancellationRefusedPartialResult = cancelConfirmed,
                    samples,
                    coldCacheControlled = false,
                    physicalDiskIoMeasured = false,
                    deliberateSpeedupClaimed = false,
                    productionOriginalReplacementEnabled = false,
                    productionHardlinkMergeEnabled = false,
                    realMediaTouched = false,
                    actualRecoveredBytes = 0,
                    verdict = "PASS"
                }, new JsonSerializerOptions { WriteIndented = true }));
            Console.WriteLine("R2.17 priority bulk scan: 1,072 generated files, four exact groups, 4 measured passes");
        }
        finally { Directory.Delete(root, true); }
    }
}
